function bootstrapLabel(b){
  if(b.ready)return 'CONCLUÍDO';
  if(b.control==='paused'||b.paused)return 'PAUSADO';
  if(b.status==='erro')return 'ERRO';
  if(b.status==='cancelado'||b.control==='cancelled')return 'CANCELADO';
  if(bootstrapOptimisticState==='resuming')return 'RETOMANDO...';
  if(bootstrapOptimisticState==='starting')return 'INICIANDO...';
  if(b.status==='aguardando_whatsapp')return 'AGUARDANDO WHATSAPP';
  if(b.status==='aguardando_historico')return 'AGUARDANDO HISTÓRICO';
  if(b.status==='aguardando_gemini')return 'AGUARDANDO GEMINI';
  return 'ANALISANDO';
}
function addBootstrapEvent(title,detail=''){
  const sig=`${title}|${detail}`;if(bootstrapEventHistory[0]?.sig===sig)return;
  bootstrapEventHistory.unshift({sig,title,detail,time:new Date()});bootstrapEventHistory=bootstrapEventHistory.slice(0,6);
  const log=document.getElementById('bootstrapEventLog');if(log)log.innerHTML=bootstrapEventHistory.map(x=>`<div class="bootstrap-event"><b>${escapeHTML(x.title)}</b>${x.detail?` · ${escapeHTML(x.detail)}`:''} <span>(${x.time.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})})</span></div>`).join('');
}
function setBootstrapButtons(b){
  const ready=!!b.ready, paused=b.control==='paused'||b.paused, cancelled=b.control==='cancelled'||b.status==='cancelado';
  const waConnected=b.whatsappConnected!==false && b.status!=='aguardando_whatsapp';
  const active=!ready&&!cancelled&&waConnected&&!['aguardando_whatsapp','aguardando_gemini'].includes(b.status);
  const pause=document.getElementById('pauseScanBtn'),resume=document.getElementById('resumeScanBtn'),cancel=document.getElementById('cancelScanBtn'),run=document.getElementById('runScanBtn');
  if(pause){pause.style.display=active&&!paused?'':'none';pause.disabled=!active||paused;}
  if(resume){resume.style.display=paused?'':'none';resume.disabled=!paused;}
  if(cancel){cancel.style.display=(active||paused)?'':'none';cancel.disabled=ready||cancelled;}
  if(run){run.disabled=!waConnected||active||paused;run.textContent=!waConnected?'📱 Conecte o WhatsApp primeiro':ready?'🔄 Refazer preparação completa':'▶ Iniciar preparação';}
}
async function loadBootstrapStatus(){
  if(!currentAgent)return;
  try{
    const b=await api('/api/bootstrap-status');
    const labels={pausado:'Preparação pausada',cancelado:'Preparação cancelada',aguardando_whatsapp:'Aguardando conexão do WhatsApp',aguardando_historico:'Aguardando histórico utilizável do WhatsApp',importando_historico:'Importando conversas do WhatsApp',aguardando_gemini:'Histórico recebido; configure o Gemini',consolidando_empresa:'Gemini está entendendo como a empresa atende',configurando_respostas:'Mapeando intenções e contexto generativo',perfilando_clientes:'Gemini está criando o perfil dos clientes',pronto:'IA pronta para atender',erro:'Erro na preparação'};
    const paused=b.control==='paused'||b.paused;
    const visibleStatus=paused?'pausado':b.status;
    const scan=document.getElementById('scanStatus');if(scan)scan.textContent=labels[visibleStatus]||visibleStatus||'-';
    const badge=document.getElementById('bootstrapReadyBadge');if(badge){badge.textContent=b.ready?'✅ IA pronta':paused?'⏸ Pausada':b.status==='erro'?'⚠️ Erro':b.status==='cancelado'?'✕ Cancelada':b.status==='aguardando_whatsapp'?'📱 Aguardando WhatsApp':b.status==='aguardando_historico'?'💬 Aguardando histórico':b.status==='aguardando_gemini'?'✦ Aguardando Gemini':'⏳ Preparando';badge.className='bootstrap-badge '+(b.ready?'ready':paused?'paused':b.status==='erro'?'error':'waiting');}
    const msgs=document.getElementById('bootstrapMessages');if(msgs){const sampled=Number(b.sampledMessages||0),total=Number(b.totalMessages||b.importedMessages||0);msgs.textContent=sampled?`${sampled.toLocaleString('pt-BR')} / ${total.toLocaleString('pt-BR')}`:total.toLocaleString('pt-BR');}
    const contacts=document.getElementById('bootstrapContacts');if(contacts)contacts.textContent=Number(b.totalContacts||0).toLocaleString('pt-BR');
    const prof=document.getElementById('bootstrapProfiled');if(prof){const target=Number(b.targetContacts||b.eligibleContacts||0);prof.textContent=`${Number(b.profiledContacts||0).toLocaleString('pt-BR')} / ${target.toLocaleString('pt-BR')}`;}
    const auto=document.getElementById('bootstrapAutomations');if(auto)auto.textContent=`${Number(b.generatedFlows||0).toLocaleString('pt-BR')} / ${Number(b.generatedQuickReplies||0).toLocaleString('pt-BR')}`;
    let pct=Number.isFinite(Number(b.percent))?Math.max(0,Math.min(100,Number(b.percent))):0,step='';
    if(['aguardando_historico','importando_historico'].includes(b.status)||b.phase==='sincronizando_historico')step='import';
    else if(['aguardando_gemini','consolidando_empresa'].includes(b.status)||['iniciando_analise','aprendendo_empresa','consolidando_memoria','configurando_respostas'].includes(b.phase))step='company';
    else if(b.status==='perfilando_clientes'||b.phase==='perfilando_clientes')step='customers';
    else if(b.status==='pronto'||b.ready)step='ready';
    const bar=document.getElementById('bootstrapProgressBar');if(bar)bar.style.width=pct+'%';
    const percentText=document.getElementById('bootstrapPercentText');if(percentText)percentText.textContent=Math.round(pct)+'%';
    const order=['import','company','customers','ready'],activeIndex=order.indexOf(step);document.querySelectorAll('.bootstrap-step').forEach((el,i)=>{el.classList.toggle('done',b.ready||i<activeIndex);el.classList.toggle('active',!b.ready&&!paused&&i===activeIndex);el.classList.toggle('paused',paused&&i===activeIndex);});
    const detail=document.getElementById('bootstrapDetail');if(detail){const deferred=Number(b.deferredContacts||0),kb=Number(b.knowledgeItems||0),gaps=Number(b.knowledgeGaps||0),pros=Number(b.prospectingDrafts||0),seeded=Number(b.seededContacts||0);detail.textContent=b.status==='aguardando_whatsapp'?'Nenhuma análise está em execução. Conecte o WhatsApp para disponibilizar o histórico antes de preparar a IA.':b.error&&!b.ready?b.error:(b.ready&&b.completedAt?`Preparação concluída em ${new Date(b.completedAt).toLocaleString('pt-BR')}: ${kb} itens na base de conhecimento, ${gaps} lacunas, ${Number(b.generatedFlows||0)} regras, ${Number(b.generatedQuickReplies||0)} respostas rápidas, ${pros} rascunhos de prospecção e ${seeded} contatos correlacionados ao CRM${deferred?`; ${deferred} perfis serão aprofundados sob demanda`:''}.`:`${b.current||'Preparando agente'} · ${Math.round(pct)}%. O agente está correlacionando histórico, CRM, conhecimento e automações.`);}
    const title=document.getElementById('bootstrapStateTitle');if(title)title.textContent=bootstrapLabel(b);
    const subtitle=document.getElementById('bootstrapStateSubtitle');if(subtitle)subtitle.textContent=paused?`Pausado em: ${b.current||b.phase||'processamento'}`:(b.error||b.current||labels[b.status]||'Aguardando início');
    const updated=document.getElementById('bootstrapUpdatedAt');if(updated)updated.textContent=b.lastUpdateAt?`Atualizado ${new Date(b.lastUpdateAt).toLocaleTimeString('pt-BR')}`:'Sem atividade recente';
    const panel=document.getElementById('bootstrapLivePanel');if(panel){panel.classList.remove('running','paused','ready','error');const panelStateClass=b.ready?'ready':paused?'paused':b.status==='erro'?'error':(!['aguardando_whatsapp','aguardando_gemini','cancelado'].includes(b.status)?'running':null);if(panelStateClass)panel.classList.add(panelStateClass);}
    const card=document.querySelector('.bootstrap-card');if(card)card.classList.toggle('is-paused',paused);
    setBootstrapButtons(b);
    const signature=[visibleStatus,b.phase,b.current,Math.round(pct)].join('|');
    if(signature!==bootstrapLastSignature){bootstrapLastSignature=signature;addBootstrapEvent(bootstrapLabel(b),b.current||labels[visibleStatus]||b.phase||'');}
    if(bootstrapOptimisticState&&((bootstrapOptimisticState==='resuming'&&!paused)||(bootstrapOptimisticState==='starting'&&b.running)))bootstrapOptimisticState='';
  }catch(e){const title=document.getElementById('bootstrapStateTitle');if(title)title.textContent='SEM COMUNICAÇÃO';const subtitle=document.getElementById('bootstrapStateSubtitle');if(subtitle)subtitle.textContent=e.message||'Não foi possível consultar a preparação.';}
}
