function openAddAgentModal(){
  if(currentAgent?.role!=='gestor')return toast('Somente o Gestor pode adicionar atendentes.','error');
  let overlay=document.getElementById('agentCreateOverlay');
  if(!overlay){overlay=document.createElement('div');overlay.id='agentCreateOverlay';overlay.className='agent-modal-overlay';document.body.appendChild(overlay);}
  overlay.innerHTML=`<div class="agent-modal" role="dialog" aria-modal="true">
    <div class="crm-header"><div><h3>+ Adicionar atendente</h3><p class="hint">Crie um acesso individual e escolha a função. As permissões iniciais seguem a função escolhida.</p></div><button id="agentModalClose">✕</button></div>
    <div class="agent-create-grid">
      <label>Nome do atendente<input id="newAgentName" autocomplete="off" placeholder="Ex.: Lucas"></label>
      <label>Função<select id="newAgentRole"><option value="atendimento">Atendimento</option><option value="comercial">Comercial</option><option value="financeiro">Financeiro</option><option value="gestor">Gestor</option></select></label>
      <label>PIN de acesso<input id="newAgentPin" type="password" inputmode="numeric" maxlength="12" placeholder="6 a 12 dígitos"></label>
      <label>Cor do usuário<input id="newAgentColor" type="color" value="#ff7a1a"></label>
      <label class="agent-span-2">Especialidades<input id="newAgentSpecialties" value="geral" placeholder="geral, vendas, retenção"></label>
    </div>
    <div id="newAgentRoleHelp" class="agent-role-help"></div>
    <div id="newAgentError" class="agent-create-error"></div>
    <div class="agent-modal-actions"><button id="agentModalCancel" class="tutorial-secondary">Cancelar</button><button id="agentModalSave">Criar atendente</button></div>
  </div>`;
  const roleHelp={atendimento:'Atendimento: CRM próprio, conversas, tarefas e respostas rápidas.',comercial:'Comercial: atendimento + prospecção e visão comercial.',financeiro:'Financeiro: atendimento financeiro, sem poderes administrativos globais.',gestor:'Gestor: acesso administrativo completo, equipe, CRM Geral, IA e configurações críticas.'};
  const role=document.getElementById('newAgentRole'),help=document.getElementById('newAgentRoleHelp');
  const renderHelp=()=>help.textContent=roleHelp[role.value]||''; role.onchange=renderHelp;renderHelp();
  const close=()=>{overlay.style.display='none';};
  document.getElementById('agentModalClose').onclick=close;document.getElementById('agentModalCancel').onclick=close;
  overlay.onclick=e=>{if(e.target===overlay)close();};
  document.getElementById('agentModalSave').onclick=async()=>{
    const err=document.getElementById('newAgentError');err.textContent='';
    const name=document.getElementById('newAgentName').value.trim(),pin=document.getElementById('newAgentPin').value.trim();
    const roleValue=role.value,color=document.getElementById('newAgentColor').value;
    const specialties=document.getElementById('newAgentSpecialties').value.split(',').map(x=>x.trim()).filter(Boolean);
    if(name.length<2){err.textContent='Informe o nome do atendente.';return;}
    if(!/^\d{6,12}$/.test(pin)){err.textContent='O PIN precisa ter de 6 a 12 dígitos.';return;}
    const btn=document.getElementById('agentModalSave');btn.disabled=true;btn.textContent='Criando...';
    try{await api('/api/agents',{method:'POST',body:{name,pin,role:roleValue,color,specialties:specialties.length?specialties:['geral']}});close();toast(`${name} adicionado à equipe.`,'ok');await loadAgentsTab();}
    catch(e){err.textContent=e.message||'Não foi possível criar o atendente.';btn.disabled=false;btn.textContent='Criar atendente';}
  };
  overlay.style.display='flex';setTimeout(()=>document.getElementById('newAgentName')?.focus(),20);
}
