function minsToTime(v){
  const n=Number(v);
  if(!Number.isFinite(n) || n<0 || n>1440) return '';
  if(n===1440) return '23:59'; // <input type="time"> não aceita 24:00.
  return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
}
function timeToMins(v){
  const raw=String(v||'').trim();
  const m=raw.match(/^(\d{2}):(\d{2})$/);
  if(!m) return null;
  const h=Number(m[1]),min=Number(m[2]);
  if(!Number.isInteger(h)||!Number.isInteger(min)||h<0||h>23||min<0||min>59) return null;
  return h*60+min;
}
function readBusinessRange(startId,endId,label){
  const a=timeToMins(document.getElementById(startId)?.value);
  const b=timeToMins(document.getElementById(endId)?.value);
  if(a===null||b===null) throw new Error(`${label}: preencha início e fim.`);
  if(b<=a) throw new Error(`${label}: o horário final precisa ser maior que o inicial.`);
  return [a,b];
}
