// ===== Alone Shield v7.5.0 — painel e kill switch =====
let shieldKillSwitchOn=false;
function updateShieldUI(shieldRuntime){
  if(!shieldRuntime)return;
  const ks=shieldRuntime.killSwitch||{};
  shieldKillSwitchOn=Boolean(ks.active);
  const ksBadge=document.getElementById('shieldKillSwitchState');
  if(ksBadge){ksBadge.textContent=ks.active?'🛑 KILL SWITCH ATIVO':'kill switch: inativo';ksBadge.style.background=ks.active?'#b3261e':'rgba(255,255,255,.08)';ksBadge.style.color=ks.active?'#fff':'inherit';}
  const ksBtn=document.getElementById('shieldKillSwitchBtn');
  if(ksBtn){ksBtn.textContent=ks.active?'✅ Desativar kill switch':'🛑 Ativar kill switch';ksBtn.className=ks.active?'':'secondary';}
  const w=shieldRuntime.warmup||{};
  const wBadge=document.getElementById('shieldWarmupBadge');
  if(wBadge){wBadge.textContent=w.active?`Aquecimento: ${Math.round((w.factor||0)*100)}% · ${w.daysRemaining||0}d restantes`:(w.firstConnectedAt?'Aquecimento: concluído':'Aquecimento: aguardando 1ª conexão');wBadge.style.background=w.active?'rgba(255,106,0,.25)':'rgba(255,255,255,.08)';}
  const cg=shieldRuntime.contentGuard||{};
  const cBadge=document.getElementById('shieldContentGuardBadge');
  if(cBadge)cBadge.textContent=cg.enabled?`Higiene de conteúdo: ativa (≥${cg.duplicateContactThreshold||5} contatos similares bloqueiam)`:'Higiene de conteúdo: desativada';
  const aBadge=document.getElementById('shieldAnomalyBadge');
  if(aBadge){aBadge.textContent=`Anomalia: pico >${cg&&shieldRuntime.anomaly?shieldRuntime.anomaly.spikeFactor:3}x média trava volume`;aBadge.title='Compara o volume de 24h com a média diária de 7 dias';}
  const cfBadge=document.getElementById('shieldConflictBadge');
  if(cfBadge){cfBadge.textContent='Conflito de sessão (409): pausa reconexão';cfBadge.title='Outra sessão usando o mesmo número interrompe a reconexão automática';}
}
const shieldKillSwitchBtn=document.getElementById('shieldKillSwitchBtn');
if(shieldKillSwitchBtn)shieldKillSwitchBtn.onclick=async()=>{
  const active=!shieldKillSwitchOn;
  const msg=active?'Ativar o kill switch bloqueia TODO envio automatizado (campanhas, proatividade, jornada, reativação, retries e aprovações pendentes) até ser desativado. Envios manuais continuam. Continuar?':'Desativar o kill switch retoma o outbound automatizado conforme as políticas. Continuar?';
  if(!confirm(msg))return;
  try{shieldKillSwitchBtn.disabled=true;const r=await api('/api/shield/kill-switch',{method:'POST',body:{active,reason:active?'Acionado pelo painel Shield':'Desativado pelo painel Shield'}});updateShieldUI(r.shieldRuntime||null);toast(active?'Kill switch ATIVO — outbound automatizado bloqueado.':'Kill switch desativado.',active?'error':'ok');}catch(e){toast(e.message,'error');}finally{shieldKillSwitchBtn.disabled=false;}
};
