// ---------- Gestão comercial ----------
function money(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});}
async function loadManagement(){
  loadAIRuntime().catch(()=>{});loadTeamPerformance().catch(()=>{});loadProactivitySettings().catch(()=>{});
  const settled=await Promise.allSettled([api('/api/dashboard'),api('/api/tasks?status=pending'),api('/api/calendar'),api('/api/quick-replies'),api('/api/alerts/abandoned?minutes=30')]);
  const val=(i,fallback)=>settled[i].status==='fulfilled'?settled[i].value:fallback;
  const d=val(0,{hot:0,warm:0,pipelineValue:0,closedValue:0,abandoned:0,pendingTasks:0,service:{}}),tasks=val(1,[]),events=val(2,[]),quick=val(3,[]),abandoned=val(4,[]);
  const failures=settled.filter(x=>x.status==='rejected').map(x=>x.reason?.message||'falha');
  if(failures.length)console.warn('Gestão carregada parcialmente:',failures);
  document.getElementById('managementMetrics').innerHTML=`<div class="metric metric-clickable" data-management-segment="hot"><b>${d.hot}</b><span>leads quentes</span></div><div class="metric metric-clickable" data-management-segment="warm"><b>${d.warm}</b><span>leads mornos</span></div><div class="metric metric-clickable" data-management-segment="pipeline"><b>${money(d.pipelineValue)}</b><span>pipeline</span></div><div class="metric metric-clickable" data-management-segment="closed"><b>${money(d.closedValue)}</b><span>fechados/ativos</span></div><div class="metric metric-clickable" data-management-segment="abandoned"><b>${d.abandoned}</b><span>precisam resposta +30min</span></div><div class="metric metric-clickable" data-management-segment="waiting_customer"><b>${d.waitingCustomer||0}</b><span>aguardando cliente</span></div><div class="metric metric-clickable" data-management-segment="pending_tasks"><b>${d.pendingTasks}</b><span>tarefas pendentes</span></div><div class="metric"><b>${d.service?.avg_response_ms?Math.round(d.service.avg_response_ms/60000)+' min':'-'}</b><span>resposta média</span></div><div class="metric metric-clickable" data-management-segment="open"><b>${d.service?.open_conversations||0}</b><span>conversas abertas</span></div>`;document.querySelectorAll('[data-management-segment]').forEach(el=>el.onclick=()=>showManagementSegment(el.dataset.managementSegment));
  document.getElementById('abandonedLeads').innerHTML=abandoned.length?abandoned.slice(0,20).map(c=>`<div class="management-item clickable" data-contact="${c.id}"><b>${escapeHTML(c.name||c.phone)}</b><small> aguardando desde ${new Date(c.last_inbound_at).toLocaleString('pt-BR')}</small></div>`).join(''):'<p class="hint">Nenhuma conversa abandonada há mais de 30 minutos.</p>';
  document.querySelectorAll('#abandonedLeads [data-contact]').forEach(el=>el.onclick=()=>openConversation(el.dataset.contact,'gestao'));
  document.getElementById('tasksList').innerHTML=tasks.length?tasks.slice(0,30).map(t=>`<div class="management-item"><div><b>${escapeHTML(t.title)}</b><small>${t.due_at?new Date(t.due_at).toLocaleString('pt-BR'):' sem prazo'}${t.contact?' · '+escapeHTML(t.contact.name||t.contact.phone)+(t.contact.last_intent?' · '+escapeHTML(t.contact.last_intent):''):''}</small></div><button data-task="${t.id}">✓</button></div>`).join(''):'<p class="hint">Sem tarefas pendentes.</p>';
  document.querySelectorAll('[data-task]').forEach(b=>b.onclick=async()=>{await api(`/api/tasks/${b.dataset.task}`,{method:'PUT',body:{status:'done'}});loadManagement();});
  document.getElementById('calendarList').innerHTML=events.length?events.slice(0,40).map(e=>`<div class="management-item"><div><b>${escapeHTML(e.title)}</b><small>${new Date(e.start_at).toLocaleString('pt-BR')} · ${escapeHTML(e.type)}${e.contact?' · '+escapeHTML(e.contact.name||e.contact.phone):''}</small></div></div>`).join(''):'<p class="hint">Agenda vazia.</p>';
  document.getElementById('quickRepliesList').innerHTML=quick.length?quick.map(q=>`<div class="management-item"><div><b>#${escapeHTML(q.shortcut)}</b> ${escapeHTML(q.title)}<small>${escapeHTML(q.type)}${q.file?' · arquivo salvo':''}</small></div><button class="danger-mini" data-delete-quick="${q.id}">×</button></div>`).join(''):'<p class="hint">Nenhuma resposta rápida.</p>';
  document.querySelectorAll('[data-delete-quick]').forEach(b=>b.onclick=async()=>{if(confirm('Excluir esta resposta rápida?')){await api(`/api/quick-replies/${b.dataset.deleteQuick}`,{method:'DELETE'});loadManagement();}});
  await loadHealth(); if(currentAgent?.role==='gestor')await Promise.all([loadRetries(),loadBackups(),loadAudit()]); else {const r=document.getElementById('retryList'),b=document.getElementById('backupList'),a=document.getElementById('auditList');if(r)r.innerHTML='<p class="hint">Fila técnica disponível para gestores.</p>';if(b)b.innerHTML='<p class="hint">Backups disponíveis para gestores.</p>';if(a)a.innerHTML='<p class="hint">Auditoria disponível para gestores.</p>';}
}

const MANAGEMENT_SEGMENT_LABELS={hot:'🔥 Leads quentes',warm:'🟡 Leads mornos',pipeline:'📈 Pipeline',closed:'✅ Fechados / ativos',abandoned:'🔴 Precisam responder +30min',waiting_customer:'🕒 Aguardando cliente',pending_tasks:'📋 Tarefas pendentes',open:'💬 Conversas abertas'};
async function showManagementSegment(segment){const panel=document.getElementById('managementSegmentPanel');if(!panel)return;panel.style.display='block';panel.innerHTML='<p class="hint">Carregando segmento…</p>';try{const r=await api(`/api/segments/${encodeURIComponent(segment)}`);const rows=r.contacts||[];panel.innerHTML=`<div class="crm-header"><div><h3>${MANAGEMENT_SEGMENT_LABELS[segment]||segment}</h3><p class="hint">${rows.length} contato(s) neste grupo. Clique para abrir a conversa ou processe a proatividade apenas nos elegíveis.</p></div><div class="chat-actions"><button id="segmentProactiveBtn" ${segment!=='waiting_customer'?'title="A proatividade só enviará para contatos realmente elegíveis"':''}>⚡ Proatividade neste grupo</button><button id="closeSegmentPanel">× Fechar</button></div></div><div class="segment-contact-list">${rows.slice(0,300).map(c=>`<div class="management-item clickable" data-segment-contact="${c.id}"><div><b>${escapeHTML(c.name||c.phone)}</b><small>${escapeHTML(c.phone)} · ${escapeHTML(c.lead_temperature||'')} · score ${Number(c.lead_score||0)}${c.last_intent?' · '+escapeHTML(c.last_intent):''}</small></div><span>${c.last_outbound_at&&(!c.last_inbound_at||new Date(c.last_outbound_at)>new Date(c.last_inbound_at))?'aguardando cliente':'abrir'}</span></div>`).join('')||'<p class="hint">Nenhum contato.</p>'}</div>`;document.querySelectorAll('[data-segment-contact]').forEach(el=>el.onclick=()=>openConversation(el.dataset.segmentContact,'gestao'));document.getElementById('closeSegmentPanel').onclick=()=>panel.style.display='none';document.getElementById('segmentProactiveBtn').onclick=async()=>{if(!confirm(`Processar agora um contato elegível de “${MANAGEMENT_SEGMENT_LABELS[segment]||segment}”? O agente respeitará horário, opt-out, silêncio, score e limite de tentativas.`))return;const out=await api('/api/proactivity/process-now',{method:'POST',body:{segment,contactIds:rows.map(x=>x.id)}});toast(out.ok?'Follow-up proativo enviado.':({account_protection_strict:'Proatividade bloqueada pela Proteção Estrita da Conta.',approval_required:'Follow-up preparado e aguardando aprovação humana.',circuit_breaker:'Circuit breaker do Safety Engine bloqueou o envio.',nothing_due:'Nenhum contato elegível neste grupo agora.',outside_business_hours:'Fora do horário de atendimento.',whatsapp_offline:'WhatsApp desconectado.',daily_limit:'Limite diário da proatividade atingido.',global_interval:'Aguarde o intervalo mínimo entre envios.'}[out.reason]||out.error||out.reason),'warn');loadProactivitySettings().catch(()=>{});};}catch(e){panel.innerHTML=`<p class="hint">${escapeHTML(e.message)}</p>`;}}
function proactiveScenarioCard(key,rule={}){
  const msgs=Array.isArray(rule.messages)?rule.messages.map(x=>String(x||'')):[];
  const list=msgs.length?msgs:[''];
  const attempts=list.map((m,i)=>`<div class="proactive-attempt" data-attempt="${i}"><div class="proactive-attempt-head"><b>Tentativa ${i+1}</b><button type="button" class="proactive-attempt-remove" title="Remover esta tentativa">✕</button></div><textarea class="proactive-attempt-text" rows="4" placeholder="Mensagem da tentativa ${i+1}...">${escapeHTML(m)}</textarea></div>`).join('');
  return `<div class="proactive-scenario" data-proactive-key="${escapeHTML(key)}"><div class="crm-header"><label class="switch-row compact"><input class="proactive-scenario-enabled" type="checkbox" ${rule.enabled!==false?'checked':''}><span><b class="proactive-label">${escapeHTML(rule.label||key)}</b></span></label><span class="hint proactive-attempt-count">${list.length} tentativa(s)</span></div><div class="flow-grid three"><label>Silêncio mínimo (h)<input class="proactive-silence" type="number" min="0" step="0.5" value="${Number(rule.silenceHours||0)}"></label><label>Score mínimo<input class="proactive-score" type="number" min="0" max="100" value="${Number(rule.minScore||0)}"></label><label>Intervalo entre tentativas (h)<input class="proactive-between" type="number" min="1" max="720" value="${Number(rule.betweenAttemptsHours||24)}"></label></div><small class="hint">Sequência de follow-ups — adicione quantas tentativas quiser, na ordem. Use {nome}, {nome_completo}, {interesse} e {plano} (oferta/serviço atual).</small><div class="proactive-attempts">${attempts}<button type="button" class="proactive-attempt-add" title="Adicionar nova tentativa">＋<br>Adicionar<br>tentativa</button></div></div>`;
}
function renumberProactiveAttempts(scenario){
  const wrap=scenario?.querySelector('.proactive-attempts');if(!wrap)return;
  wrap.querySelectorAll('.proactive-attempt').forEach((el,i)=>{el.dataset.attempt=i;const b=el.querySelector('.proactive-attempt-head b');if(b)b.textContent=`Tentativa ${i+1}`;const t=el.querySelector('.proactive-attempt-text');if(t)t.placeholder=`Mensagem da tentativa ${i+1}...`;});
  const count=scenario.querySelector('.proactive-attempt-count');if(count)count.textContent=`${wrap.querySelectorAll('.proactive-attempt').length} tentativa(s)`;
}
const proactiveScenariosBox=document.getElementById('proactiveScenarios');
if(proactiveScenariosBox)proactiveScenariosBox.addEventListener('click',e=>{
  const add=e.target.closest('.proactive-attempt-add');
  if(add){
    const scenario=add.closest('.proactive-scenario');const wrap=scenario.querySelector('.proactive-attempts');
    if(wrap.querySelectorAll('.proactive-attempt').length>=20){toast('Máximo de 20 tentativas por cenário.','warn');return;}
    const idx=wrap.querySelectorAll('.proactive-attempt').length;
    const div=document.createElement('div');div.className='proactive-attempt';div.dataset.attempt=idx;
    div.innerHTML=`<div class="proactive-attempt-head"><b>Tentativa ${idx+1}</b><button type="button" class="proactive-attempt-remove" title="Remover esta tentativa">✕</button></div><textarea class="proactive-attempt-text" rows="4" placeholder="Mensagem da tentativa ${idx+1}..."></textarea>`;
    wrap.insertBefore(div,add);renumberProactiveAttempts(scenario);div.querySelector('textarea').focus();return;
  }
  const rem=e.target.closest('.proactive-attempt-remove');
  if(rem){
    const scenario=rem.closest('.proactive-scenario');const wrap=scenario.querySelector('.proactive-attempts');
    if(wrap.querySelectorAll('.proactive-attempt').length<=1){toast('Cada cenário precisa de pelo menos uma tentativa.','warn');return;}
    rem.closest('.proactive-attempt').remove();renumberProactiveAttempts(scenario);
  }
});
async function loadProactivitySettings(){const [s,d]=await Promise.all([api('/api/settings'),api('/api/proactivity/status')]);const enabled=document.getElementById('proactiveEnabled');if(!enabled)return;enabled.checked=s.proactiveEnabled!==false;document.getElementById('proactiveGlobalInterval').value=Number(s.proactiveGlobalMinIntervalSeconds||45);document.getElementById('proactiveDailyLimit').value=Number(s.proactiveDailyLimit||80);if(document.getElementById('commercialContactWindowDays'))document.getElementById('commercialContactWindowDays').value=Number(s.commercialContactWindowDays||7);if(document.getElementById('commercialContactLimit'))document.getElementById('commercialContactLimit').value=Number(s.commercialContactLimit||10);document.getElementById('proactiveScenarios').innerHTML=Object.entries(s.proactiveScenarios||{}).map(([k,v])=>proactiveScenarioCard(k,v)).join('');document.getElementById('proactiveStatus').innerHTML=`<div class="health-item ${d.whatsapp==='conectado'?'ok':'bad'}"><span>WhatsApp</span><b>${escapeHTML(d.whatsapp)}</b></div><div class="health-item ${d.insideBusinessHours?'ok':'bad'}"><span>Horário</span><b>${d.insideBusinessHours?'dentro':'fora'}</b></div><div class="health-item ${d.accountProtectionMode==='off'?'ok':'warn'}"><span>Proteção</span><b>${escapeHTML(d.accountProtectionMode||'strict')}</b></div><div class="health-item ${d.automationMode==='automatic'?'ok':'warn'}"><span>Modo outbound</span><b>${escapeHTML(d.automationMode||'approval')}</b></div><div class="health-item ok"><span>Elegíveis agora</span><b>${d.eligible||0}</b></div><div class="health-item ok"><span>Envios hoje</span><b>${d.dailyUsed||0}/${d.dailyLimit||0}</b></div>`;}
function collectProactiveScenarios(){const out={};document.querySelectorAll('[data-proactive-key]').forEach(card=>{const key=card.dataset.proactiveKey;const messages=[...card.querySelectorAll('.proactive-attempt-text')].map(t=>String(t.value||'').trim()).filter(Boolean);out[key]={enabled:card.querySelector('.proactive-scenario-enabled').checked,label:card.querySelector('.proactive-label')?.textContent||key,silenceHours:Number(card.querySelector('.proactive-silence').value||0),minScore:Number(card.querySelector('.proactive-score').value||0),maxAttempts:Math.max(1,messages.length),betweenAttemptsHours:Number(card.querySelector('.proactive-between').value||24),messages};});return out;}

