document.getElementById('exportContactsBtn').onclick=()=>{const a=document.createElement('a');a.href='/api/export/contacts.csv?token='+encodeURIComponent(sessionToken);/* download uses header auth below via fetch */fetch('/api/export/contacts.csv',{headers:{'x-session-token':sessionToken}}).then(r=>r.blob()).then(blob=>{const u=URL.createObjectURL(blob);a.href=u;a.download='alone-ai-agent-crm.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);});};


// ---------- Inbox inteligente ----------
async function loadInbox(){
  const inboxScope=currentAgent?.canViewAllCRM?'all':(currentScope==='all'?'all':'mine');const data=await api(`/api/inbox?scope=${inboxScope}`); const c=data.counts||{};
  document.getElementById('inboxMetrics').innerHTML=`<div class="metric danger-metric metric-clickable ${activeInboxGroup==='urgent'?'active-filter':''}" data-inbox-group="urgent"><b>${c.urgent||0}</b><span>precisam responder</span></div><div class="metric metric-clickable ${activeInboxGroup==='waiting_customer'?'active-filter':''}" data-inbox-group="waiting_customer"><b>${c.waiting_customer||0}</b><span>aguardando cliente</span></div><div class="metric metric-clickable ${activeInboxGroup==='ai_attending'?'active-filter':''}" data-inbox-group="ai_attending"><b>${c.ai_attending||0}</b><span>IA atendendo</span></div><div class="metric metric-clickable ${activeInboxGroup==='human_attending'?'active-filter':''}" data-inbox-group="human_attending"><b>${c.human_attending||0}</b><span>humano atendendo</span></div><div class="metric metric-clickable ${activeInboxGroup==='followup_today'?'active-filter':''}" data-inbox-group="followup_today"><b>${c.followup_today||0}</b><span>follow-up hoje</span></div><div class="metric metric-clickable ${activeInboxGroup==='problems'?'active-filter':''}" data-inbox-group="problems"><b>${c.problems||0}</b><span>alertas</span></div>`;document.querySelectorAll('[data-inbox-group]').forEach(el=>el.onclick=()=>{activeInboxGroup=activeInboxGroup===el.dataset.inboxGroup?'':el.dataset.inboxGroup;loadInbox();});
  const labels={urgent:'🔥 Precisa responder agora',waiting_customer:'🟡 Aguardando cliente',ai_attending:'🤖 IA atendendo',human_attending:'👤 Humano atendendo',followup_today:'⏰ Follow-up hoje',problems:'⚠️ Problemas / revisão'};
  lastInboxData=data; renderInboxGroups();
  if((c.urgent||0)>lastInboxUrgent&&lastInboxUrgent>0){toast(`Há ${c.urgent} conversas pedindo atenção.`,'warn');if('Notification' in window&&Notification.permission==='granted')new Notification('Alone.AI',{body:`${c.urgent} conversas precisam de atenção.`});}lastInboxUrgent=c.urgent||0;
  document.querySelectorAll('#inboxGroups [data-contact]').forEach(el=>el.onclick=()=>openConversation(el.dataset.contact,'inbox'));
}
document.getElementById('refreshInboxBtn').onclick=loadInbox;
function renderInboxGroups(){if(!lastInboxData)return;const dep=document.getElementById('inboxDepartment')?.value||'',temp=document.getElementById('inboxTemperature')?.value||'',stage=document.getElementById('inboxStage')?.value||'',txt=(document.getElementById('inboxFilterText')?.value||'').toLowerCase();const labels={urgent:'🔥 Precisa responder agora',waiting_customer:'🟡 Aguardando cliente',ai_attending:'🤖 IA atendendo',human_attending:'👤 Humano atendendo',followup_today:'⏰ Follow-up hoje',problems:'⚠️ Problemas / revisão'};const filter=c=>(!dep||c.department===dep)&&(!temp||c.lead_temperature===temp)&&(!stage||c.journey_stage===stage)&&(!txt||[c.name,c.phone,c.tags,c.interest,c.last_intent].some(v=>String(v||'').toLowerCase().includes(txt)));const entries=activeInboxGroup?[[activeInboxGroup,labels[activeInboxGroup]]]:Object.entries(labels);document.getElementById('inboxGroups').innerHTML=(activeInboxGroup?`<div class="inbox-active-filter"><b>Filtro:</b> ${labels[activeInboxGroup]} <button id="clearInboxGroupFilter">Mostrar todas</button></div>`:'')+entries.map(([key,label])=>{const arr=(lastInboxData.groups?.[key]||[]).filter(filter);return `<div class="inbox-group"><h3>${label} <span>${arr.length}</span></h3>${arr.slice(0,200).map(c=>`<div class="inbox-contact" data-contact="${c.id}"><div><b>${escapeHTML(c.name||c.phone)}</b><small>${escapeHTML(c.interest||c.last_intent||c.phone)}</small></div><span class="mini-state">${c.ai_paused?'👤':'🤖'} ${escapeHTML(c.lead_temperature||'')}</span>${c.requires_human?'<span class="alert-dot">HUMANO</span>':''}</div>`).join('')||'<p class="hint">Nada aqui.</p>'}</div>`}).join('');document.querySelectorAll('#inboxGroups [data-contact]').forEach(el=>el.onclick=()=>openConversation(el.dataset.contact,'inbox'));const clear=document.getElementById('clearInboxGroupFilter');if(clear)clear.onclick=()=>{activeInboxGroup='';loadInbox();};}
['inboxDepartment','inboxTemperature','inboxStage','inboxFilterText'].forEach(id=>{const el=document.getElementById(id);if(el)el.oninput=renderInboxGroups;});
document.getElementById('inboxStage').innerHTML='<option value="">Todas as jornadas</option>'+JOURNEY_STAGES.map(s=>`<option value="${s}">${JOURNEY_LABELS[s]}</option>`).join('');


// ---------- Base de conhecimento ----------
function knowledgeStatusLabel(s){return ({official:'✅ Oficial',reviewed:'☑ Revisado',learned:'🧠 Aprendido',review:'⚠️ Revisar',expired:'⛔ Expirado'})[s]||s;}
function knowledgeDate(v){return v?new Date(v).toLocaleString('pt-BR'):'—';}
function clearKnowledgeForm(){
  ['knowledgeCategory','knowledgeTitle','knowledgeContent','knowledgeKeywords','knowledgeValidFrom','knowledgeExpiresAt','knowledgeReviewAfter'].forEach(x=>{const e=document.getElementById(x);if(e)e.value='';});
  document.getElementById('knowledgeStatus').value='official';document.getElementById('knowledgePriority').value=100;document.getElementById('knowledgeLocked').checked=true;
  delete document.getElementById('saveKnowledgeBtn').dataset.editId;document.getElementById('saveKnowledgeBtn').textContent='+ Adicionar conhecimento';
}
async function loadKnowledge(){
  const list=await api('/api/knowledge');loadKnowledgeGaps().catch(()=>{});
  const counts={official:0,reviewed:0,learned:0,review:0,expired:0};for(const k of list)counts[k.effective_status||k.status||'learned']=(counts[k.effective_status||k.status||'learned']||0)+1;
  const summary=document.getElementById('knowledgeSummary');if(summary)summary.innerHTML=`<div><b>${counts.official}</b><span>Oficiais</span></div><div><b>${counts.reviewed}</b><span>Revisados</span></div><div><b>${counts.learned}</b><span>Aprendidos</span></div><div><b>${counts.review}</b><span>Revisar</span></div><div><b>${counts.expired}</b><span>Expirados</span></div>`;
  document.getElementById('knowledgeList').innerHTML=list.length?list.map(k=>{const st=k.effective_status||k.status||'learned';return `<div class="knowledge-item knowledge-${st}"><div><span class="kb-category">${escapeHTML(k.category)}</span><span class="confidence-pill">${knowledgeStatusLabel(st)}</span><b>${escapeHTML(k.title)}</b><p>${escapeHTML(k.content)}</p><small>Prioridade ${Number(k.priority||0)} · ${k.locked?'🔒 protegido':'🔄 IA pode atualizar'}${k.valid_from?' · desde '+knowledgeDate(k.valid_from):''}${k.expires_at?' · até '+knowledgeDate(k.expires_at):''}${k.review_after?' · revisar '+knowledgeDate(k.review_after):''}<br>${escapeHTML((k.keywords||[]).join(', '))}</small></div><div class="knowledge-actions"><button data-edit-k="${k.id}">Editar</button>${st!=='official'?`<button data-official-k="${k.id}">✓ Oficial</button>`:''}${st!=='expired'?`<button data-expire-k="${k.id}">Expirar</button>`:''}<button class="danger-mini" data-del-k="${k.id}">×</button></div></div>`}).join(''):'<p class="hint">Nenhum conhecimento cadastrado.</p>';
  document.querySelectorAll('[data-del-k]').forEach(b=>b.onclick=async()=>{if(confirm('Excluir este conhecimento?')){await api(`/api/knowledge/${b.dataset.delK}`,{method:'DELETE'});loadKnowledge();}});
  document.querySelectorAll('[data-official-k]').forEach(b=>b.onclick=async()=>{const k=list.find(x=>x.id===Number(b.dataset.officialK));await api(`/api/knowledge/${k.id}`,{method:'PUT',body:{...k,status:'official',priority:100,locked:true,expires_at:k.expires_at||null}});loadKnowledge();});
  document.querySelectorAll('[data-expire-k]').forEach(b=>b.onclick=async()=>{const k=list.find(x=>x.id===Number(b.dataset.expireK));if(confirm(`Marcar "${k.title}" como expirado? A IA deixará de usar este item imediatamente.`)){await api(`/api/knowledge/${k.id}`,{method:'PUT',body:{...k,status:'expired',locked:true}});loadKnowledge();}});
  document.querySelectorAll('[data-edit-k]').forEach(b=>b.onclick=()=>{const k=list.find(x=>x.id===Number(b.dataset.editK));document.getElementById('knowledgeCategory').value=k.category||'';document.getElementById('knowledgeTitle').value=k.title||'';document.getElementById('knowledgeContent').value=k.content||'';document.getElementById('knowledgeKeywords').value=(k.keywords||[]).join(', ');document.getElementById('knowledgeStatus').value=k.effective_status==='expired'?'expired':(k.status||'reviewed');document.getElementById('knowledgePriority').value=Number(k.priority??80);document.getElementById('knowledgeValidFrom').value=k.valid_from?String(k.valid_from).slice(0,16):'';document.getElementById('knowledgeExpiresAt').value=k.expires_at?String(k.expires_at).slice(0,16):'';document.getElementById('knowledgeReviewAfter').value=k.review_after?String(k.review_after).slice(0,16):'';document.getElementById('knowledgeLocked').checked=k.locked!==false;document.getElementById('saveKnowledgeBtn').dataset.editId=k.id;document.getElementById('saveKnowledgeBtn').textContent='💾 Salvar e proteger';document.getElementById('knowledgeContent').focus();});
}
document.getElementById('refreshKnowledgeBtn').onclick=loadKnowledge;
async function loadKnowledgeGaps(){const gaps=await api('/api/knowledge-gaps');const box=document.getElementById('knowledgeGapsList');box.innerHTML=gaps.length?gaps.map(g=>`<div class="knowledge-gap-row"><span>${escapeHTML(g.gap)}</span><b>${g.count}×</b><button data-gap="${escapeHTML(g.gap)}">Transformar em conhecimento</button></div>`).join(''):'<p class="hint">Nenhuma lacuna recorrente detectada.</p>';box.querySelectorAll('[data-gap]').forEach(b=>b.onclick=()=>{document.getElementById('knowledgeCategory').value='FAQ';document.getElementById('knowledgeTitle').value=b.dataset.gap.slice(0,80);document.getElementById('knowledgeStatus').value='official';document.getElementById('knowledgePriority').value=100;document.getElementById('knowledgeContent').focus();});}
document.getElementById('refreshKnowledgeGapsBtn').onclick=loadKnowledgeGaps;
document.getElementById('previewKnowledgeBtn').onclick=async()=>{const content=document.getElementById('knowledgeContent').value.trim();if(!content)return alert('Preencha o conteúdo primeiro.');const question=prompt('Qual pergunta você quer usar para testar este conhecimento?','Quais são as informações sobre este tema?');if(!question)return;try{const r=await api('/api/knowledge/preview',{method:'POST',body:{category:document.getElementById('knowledgeCategory').value,title:document.getElementById('knowledgeTitle').value,content,question}});alert('Resposta de teste\n\n'+r.reply);}catch(e){alert(e.message);}};
document.getElementById('clearKnowledgeFormBtn').onclick=clearKnowledgeForm;
document.getElementById('saveKnowledgeBtn').onclick=async()=>{const id=document.getElementById('saveKnowledgeBtn').dataset.editId;const body={category:document.getElementById('knowledgeCategory').value,title:document.getElementById('knowledgeTitle').value,content:document.getElementById('knowledgeContent').value,keywords:document.getElementById('knowledgeKeywords').value,status:document.getElementById('knowledgeStatus').value,priority:Number(document.getElementById('knowledgePriority').value||0),valid_from:document.getElementById('knowledgeValidFrom').value||null,expires_at:document.getElementById('knowledgeExpiresAt').value||null,review_after:document.getElementById('knowledgeReviewAfter').value||null,locked:document.getElementById('knowledgeLocked').checked};if(!body.title.trim()||!body.content.trim())return alert('Informe título e conteúdo.');await api(id?`/api/knowledge/${id}`:'/api/knowledge',{method:id?'PUT':'POST',body});clearKnowledgeForm();loadKnowledge();};

// ---------- Templates de jornada ----------
async function loadJourneyTemplates(){const list=await api('/api/journey-templates');const box=document.getElementById('journeyTemplates');if(!box)return;box.innerHTML=list.map(t=>`<div class="template-card"><div><h4>${escapeHTML(t.name)}</h4><p>${escapeHTML(t.description||'')}</p><div class="stage-pills">${(t.stages||[]).map(x=>`<span>${escapeHTML(JOURNEY_LABELS[x]||x)}</span>`).join('')}</div></div><div><button data-edit-template="${escapeHTML(t.id)}">Editar</button>${!['lead_academia','aula_experimental','cancelado'].includes(t.id)?`<button class="danger-mini" data-del-template="${escapeHTML(t.id)}">×</button>`:''}</div></div>`).join('');document.querySelectorAll('[data-edit-template]').forEach(b=>b.onclick=()=>editJourneyTemplate(list.find(x=>String(x.id)===String(b.dataset.editTemplate))));document.querySelectorAll('[data-del-template]').forEach(b=>b.onclick=async()=>{if(confirm('Excluir template?')){await api(`/api/journey-templates/${b.dataset.delTemplate}`,{method:'DELETE'});loadJourneyTemplates();}});}
function editJourneyTemplate(t=null){const name=prompt('Nome do template:',t?.name||'Nova jornada');if(!name)return;const desc=prompt('Descrição:',t?.description||'');const defaultStages=(t?.stages||JOURNEY_STAGES).join(',');const stages=prompt(`Etapas separadas por vírgula:\n${JOURNEY_STAGES.join(', ')}`,defaultStages);if(stages==null)return;const body={name,description:desc,stages:stages.split(',').map(x=>x.trim()).filter(x=>JOURNEY_STAGES.includes(x)),active:true};api(t?`/api/journey-templates/${t.id}`:'/api/journey-templates',{method:t?'PUT':'POST',body}).then(loadJourneyTemplates).catch(e=>alert(e.message));}
document.getElementById('newJourneyTemplateBtn').onclick=()=>editJourneyTemplate();

async function loadLearningStatus(){
  const box=document.getElementById('learningMetrics'),recent=document.getElementById('learningRecent'); if(!box)return;
  try{const r=await api('/api/ai/learning-status'); box.innerHTML=`<div class="health-item ${r.enabled?'ok':'bad'}"><span>Status</span><b>${escapeHTML(r.status||'')}</b></div><div class="health-item ok"><span>Pendente</span><b>${r.pending}/${r.batch}</b></div><div class="health-item ${r.failures?'bad':'ok'}"><span>Execuções / falhas</span><b>${r.runs} / ${r.failures}</b></div><div class="health-item ok"><span>Última duração</span><b>${r.last_duration_ms?Math.round(r.last_duration_ms/1000)+' s':'-'}</b></div><div class="health-item ok"><span>Perfis atualizados</span><b>${r.last_profiled||0}</b></div><div class="health-item ok"><span>Δ conhecimento</span><b>${Number(r.last_knowledge_delta||0)>=0?'+':''}${r.last_knowledge_delta||0}</b></div>`; if(recent)recent.innerHTML=(r.recent||[]).map(x=>`<div class="management-item"><div><b>${x.action==='continuous_learning_completed'?'✅ Aprendizado concluído':'⚠️ Aprendizado falhou'}</b><small>${new Date(x.created_at).toLocaleString('pt-BR')} · ${x.details?.newMessages??'-'} mensagens · ${x.details?.profiled??0} perfis${x.details?.durationMs?' · '+Math.round(x.details.durationMs/1000)+' s':''}${x.details?.error?' · '+escapeHTML(x.details.error):''}</small></div></div>`).join('')||'<p class="hint">Ainda não há ciclos registrados.</p>';}
  catch(e){box.innerHTML=`<div class="health-item bad"><span>Aprendizado</span><b>${escapeHTML(e.message)}</b></div>`;}
}

async function loadAIRuntime(){const r=await api('/api/ai/runtime');const box=document.getElementById('aiRuntimeMetrics');if(!box)return;box.innerHTML=`<div class="health-item ok"><span>Chamadas</span><b>${r.totalCalls||0}</b></div><div class="health-item ${r.totalFailures?'bad':'ok'}"><span>Falhas</span><b>${r.totalFailures||0}</b></div><div class="health-item ok"><span>Tokens entrada</span><b>${Number(r.promptTokens||0).toLocaleString('pt-BR')}</b></div><div class="health-item ok"><span>Tokens saída</span><b>${Number(r.outputTokens||0).toLocaleString('pt-BR')}</b></div><div class="health-item ok"><span>Latência média</span><b>${r.avgLatencyMs||0} ms</b></div>`;}
async function loadTeamPerformance(){const rows=await api('/api/team-performance');const box=document.getElementById('teamPerformanceList');if(!box)return;box.innerHTML=rows.map(r=>{const a=agentById(r.agent_id);return `<div class="management-item"><div><b>${escapeHTML(a?.name||('Agente '+r.agent_id))}</b><small>${r.contacts} contatos · ${r.hot} quentes · ${r.unread} não lidas · ${r.humanReviews} revisões · ${r.active} ativos</small></div></div>`}).join('')||'<p class="hint">Sem dados.</p>';}

// ---------- Saúde / retry / backup / auditoria ----------
function healthItem(label,data){return `<div class="health-item ${data.ok?'ok':'bad'}"><span>${data.ok?'●':'●'} ${label}</span><b>${escapeHTML(data.text)}</b></div>`;}
async function loadHealth(){
  const box=document.getElementById('healthPanel');if(!box)return;
  try{
    const h=await api('/api/health');
    const geminiText=!h.gemini.configured?'não configurado':h.gemini.ok?`online · ${h.gemini.calls||0} chamadas`:`falha · ${h.gemini.failures||0} erro(s)`;
    const boot=h.bootstrap||{};const bootOk=(boot.ready&&boot.has_style_profile&&boot.has_business_profile)||['aguardando_whatsapp','importando_historico'].includes(boot.status);
    const storage=h.database?.storage||{};const storageLabel=storage.mode==='sqlite'?'SQLite':storage.mode==='json_fallback'?'JSON fallback':'armazenamento';
    box.innerHTML=healthItem('WhatsApp',{ok:h.whatsapp.ok,text:h.whatsapp.status})+healthItem('Gemini',{ok:h.gemini.ok,text:geminiText})+healthItem('Preparação IA',{ok:bootOk,text:boot.ready?'pronta':`${boot.status||'aguardando'} · ${Number(boot.percent||0)}%`})+healthItem('Banco',{ok:h.database.ok,text:`${storageLabel} · ${h.database.totalContacts||0} contatos · ${h.database.totalMessages||0} msgs`})+healthItem('Agendador',{ok:h.scheduler.ok,text:h.scheduler.ok?'ativo':'parado'})+healthItem('Retry',{ok:h.retry_queue.ok,text:`${h.retry_queue.pending} pendentes / ${h.retry_queue.dead} críticos`})+healthItem('Backup',{ok:h.backup.ok,text:h.backup.last_at?new Date(h.backup.last_at).toLocaleString('pt-BR'):'nunca'});
    const detail=document.getElementById('healthDetails');if(detail){const rows=[];if(h.gemini.last_error)rows.push(`Gemini: ${h.gemini.last_error}`);if(boot.error)rows.push(`Preparação: ${boot.error}`);if(boot.ready&&!boot.has_style_profile)rows.push('Preparação: marcada como pronta, mas o perfil de estilo não foi persistido.');if(boot.ready&&!boot.has_business_profile)rows.push('Preparação: marcada como pronta, mas a memória operacional não foi persistida.');if(boot.quality)rows.push(`Preparação: qualidade ${boot.quality} · ${boot.sampled_messages||0} msgs amostradas · ${boot.profiled_contacts||0} perfis iniciais.`);if(storage.mode==='json_fallback'&&storage.fallback_reason)rows.push(`Banco: fallback JSON — ${storage.fallback_reason}`);for(const e of (boot.diagnostics?.errors||[]))rows.push(`Lote ${e.chunk}: ${e.error}`);detail.textContent=rows.length?rows.join('\n'):'Sem erros técnicos ativos.';}
    const updated=document.getElementById('healthUpdatedAt');if(updated)updated.textContent=`Atualizado: ${new Date(h.generated_at||Date.now()).toLocaleTimeString('pt-BR')}`;
  }catch(e){box.innerHTML=healthItem('Backend',{ok:false,text:e.message});const detail=document.getElementById('healthDetails');if(detail)detail.textContent=e.message;}
}
function startHealthAutoRefresh(){if(healthAutoTimer)clearInterval(healthAutoTimer);healthAutoTimer=setInterval(()=>{if(currentAgent&&document.getElementById('tab-gestao')?.classList.contains('active'))loadHealth().catch(()=>{});},5000);}
async function loadRetries(){const [jobs,all]=await Promise.all([api('/api/retries?limit=30'),api('/api/operations-queue')]),metrics={pending:0,processing:0,dead:0};jobs.forEach(j=>{if(metrics[j.status]!=null)metrics[j.status]++;});document.getElementById('retryMetrics').innerHTML=`<div class="mini-stat"><b>${metrics.pending}</b> retries · <b>${all.prospecting?.length||0}</b> prospecção · <b>${all.journey?.length||0}</b> follow-ups · <b>${metrics.dead}</b> críticos</div>`;document.getElementById('retryList').innerHTML=jobs.filter(j=>j.status!=='done').slice(0,15).map(j=>`<div class="management-item"><div><b>#${j.id} ${escapeHTML(j.kind)}</b><small>${escapeHTML(j.status)} · tentativa ${j.attempts}/${j.max_attempts}${j.next_attempt_at?' · próxima '+new Date(j.next_attempt_at).toLocaleString('pt-BR'):''}${j.last_error?' · '+escapeHTML(j.last_error):''}</small></div><button data-retry-now="${j.id}">Tentar agora</button></div>`).join('')||'<p class="hint">Sem retries pendentes. A fila operacional continua monitorando prospecção e follow-ups.</p>';document.querySelectorAll('[data-retry-now]').forEach(b=>b.onclick=async()=>{await api(`/api/retries/${b.dataset.retryNow}/now`,{method:'POST',body:{}});await api('/api/retries/process-now',{method:'POST',body:{}});loadRetries();});}
async function loadBackups(){const list=await api('/api/backups');document.getElementById('backupList').innerHTML=list.slice(0,14).map(b=>`<div class="management-item"><div><b>${escapeHTML(b.name)}</b></div><button data-restore="${escapeHTML(b.name)}">Restaurar</button></div>`).join('')||'<p class="hint">Nenhum backup criado.</p>';document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{if(!confirm('Restaurar este backup? O sistema cria um backup de segurança antes. Será necessário reiniciar o programa.'))return;const r=await api(`/api/backups/${encodeURIComponent(b.dataset.restore)}/restore`,{method:'POST',body:{}});alert(r.restartRequired?'Backup restaurado. Reinicie o Alone.AI para carregar completamente os dados.':'Backup restaurado.');});}
async function loadAudit(){const rows=await api('/api/audit?limit=80');document.getElementById('auditList').innerHTML=rows.map(a=>`<div class="audit-row"><span>${new Date(a.created_at).toLocaleString('pt-BR')}</span><b>${escapeHTML(a.action)}</b><small>${escapeHTML(a.resource||'')} ${a.resource_id?('#'+a.resource_id):''}${a.agent_id?' · agente '+a.agent_id:''}</small></div>`).join('')||'<p class="hint">Sem eventos.</p>';}
document.getElementById('refreshHealthBtn').onclick=loadHealth;
if(document.getElementById('cleanupQuickMediaBtn'))document.getElementById('cleanupQuickMediaBtn').onclick=async()=>{const r=await api('/api/quick-replies/cleanup-media',{method:'POST',body:{}});toast(`Limpeza concluída: ${r.removed||0} arquivo(s) removido(s).`,'ok');};document.getElementById('processRetryBtn').onclick=async()=>{const r=await api('/api/retries/process-now',{method:'POST',body:{}});if(!r.ok&&r.reason!=='nothing_due')alert(r.error||r.reason);loadManagement();};document.getElementById('createBackupBtn').onclick=async()=>{await api('/api/backups',{method:'POST',body:{label:'manual'}});loadManagement();};document.getElementById('refreshAuditBtn').onclick=loadAudit;

// ---------- Busca global + atalhos ----------
const searchInput=document.getElementById('globalSearchInput'),searchOverlay=document.getElementById('searchOverlay');let searchTimer=null;
async function runGlobalSearch(){const q=searchInput.value.trim();if(!q){searchOverlay.style.display='none';return;}const r=await api('/api/search?q='+encodeURIComponent(q));searchOverlay.style.display='flex';document.getElementById('searchResults').innerHTML=`<h4>Contatos</h4>${r.contacts.map(c=>`<div class="search-result" data-contact="${c.id}"><b>${escapeHTML(c.name||c.phone)}</b><small>${escapeHTML(c.phone)} · ${escapeHTML(c.interest||c.tags||'')}</small></div>`).join('')||'<p class="hint">Nenhum contato.</p>'}<h4>Mensagens</h4>${r.messages.slice(0,30).map(m=>`<div class="search-result" data-contact="${m.contact_id}"><b>${escapeHTML(m.contact?.name||m.contact?.phone||'Contato')}</b><small>${escapeHTML(m.body).slice(0,220)}</small></div>`).join('')||'<p class="hint">Nenhuma mensagem.</p>'}`;document.querySelectorAll('#searchResults [data-contact]').forEach(el=>el.onclick=()=>{searchOverlay.style.display='none';openConversation(el.dataset.contact,'search');});}
searchInput.oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(runGlobalSearch,250);};document.getElementById('closeSearchBtn').onclick=()=>searchOverlay.style.display='none';searchOverlay.onclick=e=>{if(e.target===searchOverlay)searchOverlay.style.display='none';};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchInput.focus();searchInput.select();}if(e.key==='Escape')searchOverlay.style.display='none';if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&activeConversationId&&document.getElementById('chatInput'))sendManual(activeConversationId);});


// Controles dos tutoriais
const tutorialOverlay=document.getElementById('tutorialOverlay');
if(document.getElementById('tutorialCloseBtn'))document.getElementById('tutorialCloseBtn').onclick=()=>closeTutorial();
if(document.getElementById('tutorialSkipBtn'))document.getElementById('tutorialSkipBtn').onclick=()=>closeTutorial({skip:true});
if(document.getElementById('tutorialBackBtn'))document.getElementById('tutorialBackBtn').onclick=()=>{if(tutorialState.index>0){tutorialState.index--;renderTutorialStep();}};
if(document.getElementById('tutorialNextBtn'))document.getElementById('tutorialNextBtn').onclick=()=>{if(tutorialState.index<tutorialState.steps.length-1){tutorialState.index++;renderTutorialStep();}else closeTutorial();};
if(document.getElementById('tutorialDontShowAgain'))document.getElementById('tutorialDontShowAgain').onchange=e=>{setTutorialHidden(tutorialState.key,e.target.checked);setTutorialsAutoDisabled(e.target.checked);};
if(tutorialOverlay)tutorialOverlay.onclick=e=>{if(e.target===tutorialOverlay)closeTutorial();};
if(document.getElementById('startMainTutorialBtn'))document.getElementById('startMainTutorialBtn').onclick=()=>openTutorial('geral',{force:true});
if(document.getElementById('resetTutorialsBtn'))document.getElementById('resetTutorialsBtn').onclick=()=>{if(confirm('Mostrar novamente todos os tutoriais para este usuário?'))resetAllTutorials();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('tutorialOverlay')?.style.display==='flex')closeTutorial();});

boot();
const clearGeminiKeyBtn=document.getElementById('clearGeminiKeyBtn');if(clearGeminiKeyBtn)clearGeminiKeyBtn.onclick=async()=>{if(!confirm('Remover a chave Gemini salva deste computador? A IA ficará indisponível até configurar outra chave.'))return;try{await api('/api/settings',{method:'POST',body:{clearGeminiApiKey:true,aiEnabled:false}});document.getElementById('geminiKeyInput').value='';toast('Chave Gemini removida.','ok');loadAITab();}catch(e){toast(e.message,'error');}};


setTimeout(()=>{const l=document.getElementById('refreshLearningStatusBtn');if(l)l.onclick=loadLearningStatus;},0);
